    pSymbol p
  elif (p.tok.kind in {tkAddr..tkYield}):
    emitLeaf p            # KEYW
  else:
    ruleError p, "symbolOrKeyword", false
  discardUnused m0

proc pLiteral*(p: var Parser) =
  let m0 = mark(p)
