  elif (p.tok.kind in {tkInt32Lit}):
    emitLeaf p            # INT32_LIT
  elif (p.tok.kind in {tkInt64Lit}):
    emitLeaf p            # INT64_LIT
  elif (p.tok.kind in {tkUIntLit}):
    emitLeaf p            # UINT_LIT
  elif (p.tok.kind in {tkUInt8Lit}):
    emitLeaf p            # UINT8_LIT
  elif (p.tok.kind in {tkUInt16Lit}):
