  elif (p.tok.kind in {tkFloat32Lit}):
    emitLeaf p            # FLOAT32_LIT
  elif (p.tok.kind in {tkFloat64Lit}):
    emitLeaf p            # FLOAT64_LIT
  elif (p.tok.kind in {tkFloat128Lit}):
    emitLeaf p            # FLOAT128_LIT
  elif (p.tok.kind in {tkStrLit}):
