proc pExprColonEqExpr*(p: var Parser) =
  let m0 = mark(p)
  if (p.tok.kind in Tk2):
    pExpr p
    if (p.tok.kind in {tkColon, tkEquals}):
      var at21 = p.info
      if (p.tok.kind in {tkColon}):
        expect p, tkColon
        pExpr p
        wrapAt p, m0, KvL, at21
      elif (p.tok.kind in {tkEquals}):
        expect p, tkEquals
        pExpr p
        wrapAt p, m0, VvL, at21
      else:
        ruleError p, "exprColonEqExpr", false
    elif (p.tok.kind in {tkDo} and indClass(p) in {icNoInd}):
      if (p.tok.kind in {tkDo} and indClass(p) in {icNoInd}):
        let m22 = mark(p)
        checkInd p, {icNoInd}
        pDoBlock(p, true)
        while (p.tok.kind in Tk15 and indClass(p) in {icEq}):
          let m23 = mark(p)
          pExtraPostExprBlock p
          discardUnused m23
        discardUnused m22
      let m = m0
      attachBlocks p, m
    else:
      if (p.tok.kind in {tkDo} and indClass(p) in {icNoInd}):
        let m24 = mark(p)
        checkInd p, {icNoInd}
        pDoBlock(p, true)
        while (p.tok.kind in Tk15 and indClass(p) in {icEq}):
          let m25 = mark(p)
          pExtraPostExprBlock p
          discardUnused m25
        discardUnused m24
      let m = m0
      attachBlocks p, m
  else:
    ruleError p, "exprColonEqExpr", false
  discardUnused m0

proc pExprEqExpr*(p: var Parser) =
  let m0 = mark(p)
  if (p.tok.kind in Tk2):
    pExpr p
    if (p.tok.kind in {tkEquals}):
      var at26 = m0.info
      at26 = p.info
      expect p, tkEquals
      pExpr p
      wrapAt p, m0, VvL, at26
    elif (p.tok.kind in {tkDo} and indClass(p) in {icNoInd}):
      if (p.tok.kind in {tkDo} and indClass(p) in {icNoInd}):
        let m27 = mark(p)
        checkInd p, {icNoInd}
        pDoBlock(p, true)
        while (p.tok.kind in Tk15 and indClass(p) in {icEq}):
          let m28 = mark(p)
          pExtraPostExprBlock p
          discardUnused m28
        discardUnused m27
      let m = m0
      attachBlocks p, m
    else:
      if (p.tok.kind in {tkDo} and indClass(p) in {icNoInd}):
        let m29 = mark(p)
        checkInd p, {icNoInd}
        pDoBlock(p, true)
        while (p.tok.kind in Tk15 and indClass(p) in {icEq}):
          let m30 = mark(p)
          pExtraPostExprBlock p
          discardUnused m30
        discardUnused m29
      let m = m0
      attachBlocks p, m
  else:
    ruleError p, "exprEqExpr", false
  discardUnused m0

proc pExprList*(p: var Parser) =
  let m0 = mark(p)
  let m31 = mark(p)
  pExpr p
  while (p.tok.kind in {tkComma}):
    pComma p
    pExpr p
  discardUnused m31
  discardUnused m0

proc pExprColonEqExprList*(p: var Parser; close: TokKind) =
  let m0 = mark(p)
  pExprColonEqExpr p
  while (p.tok.kind in {tkComma}):
    let m32 = mark(p)
    pComma p
    let m33 = mark(p)
    if (p.tok.kind in Tk2):
      pExprColonEqExpr p
    else:
      pListEnd(p, close)
    discardUnused m33
    discardUnused m32
  discardUnused m0

proc pListEnd*(p: var Parser; close: TokKind) =
  let m0 = mark(p)
  let m = m0
  listEnd p, close
  discardUnused m0

proc pQualifiedIdent*(p: var Parser) =
  let m0 = mark(p)
  if (p.tok.kind in Tk14):
    pSymbol p
    if (p.tok.kind in {tkDot}):
      var at34 = m0.info
      at34 = p.info
      expect p, tkDot
      pOptInd p
      pSymbolOrKeyword p
      wrapAt p, m0, DotL, at34
    else:
      discard
  else:
    ruleError p, "qualifiedIdent", false
  discardUnused m0

proc pSetOrTableConstr*(p: var Parser) =
  let m0 = mark(p)
  if (p.tok.kind in {tkCurlyLe}):
    expect p, tkCurlyLe
    if (p.tok.kind in Tk16 and indClass(p) in {icNoInd, icGt}) or (p.tok.kind in {tkComment} and indClass(p) in {icNoInd}):
      pOptInd p
      let m35 = mark(p)
      if (p.tok.kind in Tk2):
        pExprColonEqExprList(p, tkCurlyRi)
      else:
        pListEnd(p, tkCurlyRi)
      discardUnused m35
      pOptPar p
      expect p, tkCurlyRi
      wrap p, m0, CurlyL
      let m = m0
      curlyOrTable p, m
    elif (p.tok.kind in {tkColon}):
      expect p, tkColon
      pOptPar p
      expect p, tkCurlyRi
      wrap p, m0, TabconstrL
    else:
      ruleError p, "setOrTableConstr", (p.tok.kind in {tkComment} and indClass(p) in {icLt, icEq, icGt}) or (p.tok.kind in Tk16 and indClass(p) in {icLt, icEq})
  else:
    ruleError p, "setOrTableConstr", false
  discardUnused m0

proc pCastExpr*(p: var Parser) =
  let m0 = mark(p)
  if (p.tok.kind in {tkCast}):
    expect p, tkCast
    if (p.tok.kind in {tkBracketLe}):
      expect p, tkBracketLe
      pOptInd p
      pTypeDesc p
      pOptPar p
      expect p, tkBracketRi
      expect p, tkParLe
      pOptInd p
      pExpr p
      pOptPar p
      expect p, tkParRi
      wrap p, m0, CastL
    elif (p.tok.kind in {tkParLe}):
      expect p, tkParLe
      emitEmpty p
      pOptInd p
      pExprColonEqExpr p
      pOptPar p
      expect p, tkParRi
      wrap p, m0, CastL
    else:
      ruleError p, "castExpr", false
  else:
    ruleError p, "castExpr", false
  discardUnused m0

proc pParKeyw*(p: var Parser) =
  let m0 = mark(p)
  let m36 = mark(p)
  if (p.tok.kind in {tkDiscard}):
    expect p, tkDiscard
  elif (p.tok.kind in {tkInclude}):
    expect p, tkInclude
  elif (p.tok.kind in {tkIf}):
    expect p, tkIf
  elif (p.tok.kind in {tkWhile}):
    expect p, tkWhile
  elif (p.tok.kind in {tkCase}):
    expect p, tkCase
  elif (p.tok.kind in {tkTry}):
    expect p, tkTry
  elif (p.tok.kind in {tkFinally}):
    expect p, tkFinally
  elif (p.tok.kind in {tkExcept}):
    expect p, tkExcept
  elif (p.tok.kind in {tkFor}):
    expect p, tkFor
  elif (p.tok.kind in {tkBlock}):
    expect p, tkBlock
  elif (p.tok.kind in {tkConst}):
    expect p, tkConst
  elif (p.tok.kind in {tkLet}):
    expect p, tkLet
  elif (p.tok.kind in {tkWhen}):
    expect p, tkWhen
  elif (p.tok.kind in {tkVar}):
    expect p, tkVar
  elif (p.tok.kind in {tkMixin}):
    expect p, tkMixin
  else:
    ruleError p, "parKeyw", false
  discardUnused m36
  discardUnused m0

proc pSemiStmtItem*(p: var Parser) =
  let m0 = mark(p)
  let m37 = mark(p)
  if (p.tok.kind in {tkIf}):
    pIfExpr p
  elif (p.tok.kind in {tkWhen}):
    pWhenExpr p
  elif (p.tok.kind in Tk8):
    pComplexOrSimpleStmt p
  else:
    ruleError p, "semiStmtItem", false
  discardUnused m37
  discardUnused m0

proc pSemiStmtList*(p: var Parser) =
  let m0 = mark(p)
  inc p.inSemiStmtList
  pSemiStmtItem p
  while (p.tok.kind in Tk10):
    let m38 = mark(p)
    let m39 = mark(p)
    if (p.tok.kind in {tkSemiColon}):
      expect p, tkSemiColon
      if (p.tok.kind in Tk8):
        let m40 = mark(p)
        pSemiStmtItem p
        discardUnused m40
    elif (p.tok.kind in Tk8):
      pSemiStmtItem p
    else:
      ruleError p, "semiStmtList", false
    discardUnused m39
    discardUnused m38
  dec p.inSemiStmtList
  discardUnused m0

proc pPar*(p: var Parser) =
  let m0 = mark(p)
  if (p.tok.kind in {tkParLe}):
    expect p, tkParLe
    if (p.tok.kind in Tk10 and indClass(p) in {icNoInd, icGt}):
      pOptInd p
      if (p.tok.kind in Tk17):
        pushIndAny p
        pSemiStmtList p
        popInd p
        pOptPar p
        expect p, tkParRi
        let m = m0
        stmtListExprLayout p, m
      elif (p.tok.kind in {tkSemiColon}):
        expect p, tkSemiColon
        if (p.tok.kind in Tk8):
          let m41 = mark(p)
          pushIndAny p
          pSemiStmtList p
          popInd p
          discardUnused m41
        pOptPar p
        expect p, tkParRi
        let m = m0
        stmtListExprLayout p, m
      elif (p.tok.kind in {tkCurlyDotLe}):
        pPragmaStmt p
        pOptPar p
