          expect p, tkColon
          pExpr p
          wrapAt p, m0, KvL, at47
          discardUnused m46
          while (p.tok.kind in {tkColon}):
            let m46 = mark(p)
            var at48 = p.info
            expect p, tkColon
            pExpr p
            wrapAt p, m0, KvL, at48
            discardUnused m46
          while (p.tok.kind in {tkComma}):
            let m49 = mark(p)
            pComma p
            let m50 = mark(p)
            if (p.tok.kind in Tk2):
