        elif (p.tok.kind in Tk2):
          pExprColonEqExpr p
          if (p.tok.kind in {tkParRi} and indClass(p) in {icNoInd, icEq, icGt}):
            pOptPar p
            expect p, tkParRi
            wrap p, m0, ParL
          elif (p.tok.kind in {tkComma}):
            pComma p
            while (p.tok.kind in Tk2):
              let m54 = mark(p)
              pExprColonEqExpr p
              if (p.tok.kind in {tkComma}):
