proc pIdentOrLiteral*(p: var Parser; mode: PrimaryMode) =
  let m0 = mark(p)
  if (p.tok.kind in Tk1):
    let m58 = mark(p)
    if (p.tok.kind in {tkGStrLit, tkGTripleStrLit}):
