    elif (p.tok.kind in {tkCurlyLe}):
      var at65 = p.info
      expect p, tkCurlyLe
      if (p.tok.kind in {tkComment} and indClass(p) in {icNoInd, icGt}):
        let m66 = mark(p)
        pFlexComment p
        discardUnused m66
      pOptPar p
      let m67 = mark(p)
      if (p.tok.kind in Tk2):
