      discardUnused m67
      pOptPar p
      expect p, tkCurlyRi
      wrapAt p, anchor, CurlyatL, at65
    else:
      ruleError p, "primarySuffix", false
  elif (p.tok.kind in {tkDot}):
    var at68 = p.info
    expect p, tkDot
    pOptInd p
    pSymbolOrKeyword p
    if ((p.tok.kind in {tkBracketLeColon})) and noSpaceBefore(p):
      let m69 = mark(p)
