      pStmt p
      discardUnused m127
    else:
      emitEmpty p
    let m = Mark(pos: m0.pos, info: at126)
    procLayout p, m, ProcL
  elif (p.tok.kind in {tkFunc}):
    var at129 = m0.info
    expect p, tkFunc
    at129 = p.info
    pRoutineSig p
    let m130 = mark(p)
    if ((p.tok.kind in {tkEquals})) and routineBodyAllowed(p, mode):
