        let m131 = mark(p)
        pTrailComment p
        discardUnused m131
      pStmt p
    elif false:
      emitEmpty p
      pFuncType p
    else:
      emitEmpty p
      pFuncType p
    discardUnused m130
    let m = Mark(pos: m0.pos, info: at129)
    procLayout p, m, FuncL
  elif (p.tok.kind in {tkIterator}):
    var at132 = m0.info
    expect p, tkIterator
    at132 = p.info
    pRoutineSig p
    if ((p.tok.kind in {tkEquals})) and routineBodyAllowed(p, mode):
