  elif (p.tok.kind in {tkEnum}):
    expectLeaf p, tkEnum
  elif (p.tok.kind in {tkObject}):
    expect p, tkObject
    wrap p, m139, ObjectL
  elif (p.tok.kind in {tkVar}):
    expect p, tkVar
    if canTypeKAuxOperand(p, mode):
      let m140 = mark(p)
      pTypeKAuxOperand(p, mode)
      discardUnused m140
    wrap p, m139, MutL
  elif (p.tok.kind in {tkOut}):
    expect p, tkOut
    if canTypeKAuxOperand(p, mode):
      let m141 = mark(p)
      pTypeKAuxOperand(p, mode)
      discardUnused m141
    wrap p, m139, OutL
  elif (p.tok.kind in {tkRef}):
    expect p, tkRef
    if canTypeKAuxOperand(p, mode):
      let m142 = mark(p)
      pTypeKAuxOperand(p, mode)
      discardUnused m142
    wrap p, m139, RefL
  elif (p.tok.kind in {tkPtr}):
    expect p, tkPtr
    if canTypeKAuxOperand(p, mode):
      let m143 = mark(p)
      pTypeKAuxOperand(p, mode)
      discardUnused m143
    wrap p, m139, PtrL
  elif (p.tok.kind in {tkDistinct}):
    expect p, tkDistinct
    if canTypeKAuxOperand(p, mode):
      let m144 = mark(p)
      pTypeKAuxOperand(p, mode)
      discardUnused m144
    wrap p, m139, DistinctL
  else:
    ruleError p, "typeDescKeyw", false
  discardUnused m139
  if (p.tok.kind in {tkNot} and indClass(p) in {icNoInd}):
    let m145 = mark(p)
    checkInd p, {icNoInd}
    var at146 = p.info
    insertTokAt p, m0, tkNot
    pPrimary(p, pmTypeDesc)
    at146 = p.info
    wrapAt p, m0, InfixL, at146
    discardUnused m145
  discardUnused m0

proc pTypeKAuxOperand*(p: var Parser; mode: PrimaryMode) =
  let m0 = mark(p)
  if ((p.tok.kind in Tk3 and indClass(p) in {icNoInd, icGt})) and isTypedefOperand(p, mode):
    pValidInd p
    pTypeDefValue p
  elif ((p.tok.kind in Tk4 and indClass(p) in {icNoInd, icGt})) and typeOperandFollows(p):
