    pPrimary(p, mode)
  else:
    ruleError p, "typeKAuxOperand", (p.tok.kind in Tk3 and indClass(p) in {icLt, icEq}) or indClass(p) notin {icNoInd, icGt}
  discardUnused m0

proc pTypeDescExpr*(p: var Parser) =
