    pComma p
    if (p.tok.kind in {tkAccent, tkSymbol}):
      let m150 = mark(p)
      pForTupleVar p
      discardUnused m150
    discardUnused m149
  pOptPar p
  expect p, tkParRi
  wrap p, m0, UnpacktupL
  discardUnused m0

proc pForHead*(p: var Parser) =
  let m0 = mark(p)
  if (p.tok.kind in {tkParLe}):
    pForTuple p
    expect p, tkIn
    pExpr p
    let m = m0
    moveLastToMark p, m
  elif (p.tok.kind in {tkAccent, tkSymbol}):
    pForVar p
    while (p.tok.kind in {tkComma}):
      let m151 = mark(p)
      pComma p
      let m152 = mark(p)
      if (p.tok.kind in {tkAccent, tkSymbol}):
        pForVar p
      elif (p.tok.kind in {tkParLe}):
        pForTuple p
      else:
        ruleError p, "forHead", false
      discardUnused m152
      discardUnused m151
    wrap p, m0, UnpackflatL
    expect p, tkIn
    pExpr p
    let m = m0
    moveLastToMark p, m
  else:
    ruleError p, "forHead", false
  discardUnused m0

proc pForStmt*(p: var Parser) =
  let m0 = mark(p)
  var at153 = m0.info
  expect p, tkFor
  at153 = p.info
  pForHead p
  pColcom p
  pStmt p
  wrapAt p, m0, ForL, at153
  discardUnused m0

proc pForExpr*(p: var Parser) =
  let m0 = mark(p)
  pForStmt p
  discardUnused m0

proc pExpr*(p: var Parser) =
  let m0 = mark(p)
  if (p.tok.kind in Tk20):
    let m154 = mark(p)
    if (p.tok.kind in {tkBlock}):
      pBlockExpr p
    elif (p.tok.kind in {tkIf}):
      pIfExpr p
    elif (p.tok.kind in {tkWhen}):
      pWhenExpr p
    elif (p.tok.kind in {tkCase}):
      pCaseStmt p
    elif (p.tok.kind in {tkFor}):
      pForExpr p
    elif (p.tok.kind in {tkTry}):
      pTryExpr p
    else:
      ruleError p, "expr", false
    discardUnused m154
  elif (p.tok.kind in Tk4):
    pSimpleExpr(p, -1, pmNormal)
  else:
    ruleError p, "expr", false
  discardUnused m0

proc pSimplePrimary*(p: var Parser; mode: PrimaryMode) =
  let m0 = mark(p)
  pIdentOrLiteral(p, mode)
  while (canPrimarySuffix(p, mode)) and suffixStart(p):
    let m155 = mark(p)
    pPrimarySuffix(p, m0, mode)
    discardUnused m155
  if (canCommandSuffix(p, mode)) and suffixStart(p):
    let m156 = mark(p)
    pCommandSuffix(p, m0, mode)
    discardUnused m156
  discardUnused m0

proc pCommandParam*(p: var Parser; mode: PrimaryMode) =
  let m0 = mark(p)
  if ((p.tok.kind in Tk4)) and inTypeDesc(p, mode):
    pSimpleExpr(p, -1, mode)
  else:
    pExpr p
    if (p.tok.kind in {tkDo} and indClass(p) in {icNoInd}):
      let m157 = mark(p)
      checkInd p, {icNoInd}
      pDoBlock(p, true)
      while (p.tok.kind in Tk15 and indClass(p) in {icEq}):
        let m158 = mark(p)
        pExtraPostExprBlock p
        discardUnused m158
      discardUnused m157
    let m = m0
    attachBlocks p, m
  discardUnused m0

proc pPrimary*(p: var Parser; mode: PrimaryMode) =
  let m0 = mark(p)
  if (p.tok.kind in Tk5):
    pSimplePrimary(p, mode)
  elif ((p.tok.kind in Tk6)) and isSigilLike(p):
    pPrefixOperator p
    let m159 = mark(p)
    if (p.tok.kind in Tk5):
      pIdentOrLiteral(p, mode)
    else:
      pPrimary(p, pmNormal)
    discardUnused m159
    wrap p, m0, PrefixL
    while (canPrimarySuffix(p, mode)) and suffixStart(p):
      let m160 = mark(p)
      pPrimarySuffix(p, m0, mode)
      discardUnused m160
    if (canCommandSuffix(p, mode)) and suffixStart(p):
      let m161 = mark(p)
      pCommandSuffix(p, m0, mode)
      discardUnused m161
  elif ((p.tok.kind in Tk6)) and isUnary(p):
    pOperatorB p
    pPrimary(p, mode)
    wrap p, m0, PrefixL
  elif (p.tok.kind in {tkFunc, tkIterator, tkProc}):
    pRoutineExpr(p, mode)
  elif (p.tok.kind in {tkBind}):
    expect p, tkBind
    pOptInd p
    pPrimary(p, pmNormal)
    wrap p, m0, BindL
  elif (p.tok.kind in Tk7):
    pTypeDescKeyw(p, mode)
  elif (p.tok.kind in Tk6):
    pPrefixOperator p
    pPrimary(p, mode)
    wrap p, m0, PrefixL
  else:
    ruleError p, "primary", false
  discardUnused m0

proc pSimpleExpr*(p: var Parser; limit: int, mode: PrimaryMode) =
  let m0 = mark(p)
  pPrimaryPragma(p, mode)
  var prec = getPrecedence(p)
  while prec >= limit and indClass(p) == icNoInd:
    let assoc = (if isRightAssoc(p): 0 else: 1)
    let opInfo = p.info
    insertLeafAt p, m0, p.tok.s
    getTok p
    afterOperator p
    pSimpleExpr(p, prec + assoc, rhsMode(mode))
    wrapAt p, m0, InfixL, opInfo
    prec = getPrecedence(p)
  discardUnused m0

proc pPrimaryPragma*(p: var Parser; mode: PrimaryMode) =
  let m0 = mark(p)
  pPrimary(p, mode)
  if ((p.tok.kind in {tkCurlyDotLe} and indClass(p) in {icNoInd, icGt})) and pragmaOnPrimary(p, mode):
    let m162 = mark(p)
    pValidInd p
    var at163 = p.info
    pPragma p
    wrapAt p, m0, PragmaxL, at163
    discardUnused m162
  discardUnused m0

proc pExtraPostExprBlock*(p: var Parser) =
  let m0 = mark(p)
  if (p.tok.kind in Tk15 and indClass(p) in {icEq}):
    checkInd p, {icEq}
    if (p.tok.kind in {tkDo}):
      pDoBlock(p, false)
    elif (p.tok.kind in {tkOf}):
      expect p, tkOf
      pExprList p
      wrap p, m0, RangesL
      expect p, tkColon
      pStmt p
      wrap p, m0, OfL
    elif (p.tok.kind in {tkElif}):
      expect p, tkElif
      pExpr p
      expect p, tkColon
      pStmt p
      wrap p, m0, ElifL
    elif (p.tok.kind in {tkExcept}):
      expect p, tkExcept
      if (p.tok.kind in Tk2):
        let m164 = mark(p)
        let m165 = mark(p)
        pExpr p
        while (p.tok.kind in {tkComma}):
          pComma p
          pExpr p
        discardUnused m165
        discardUnused m164
      else:
        emitEmpty p
      expect p, tkColon
      pStmt p
      wrap p, m0, ExceptL
    elif (p.tok.kind in {tkFinally}):
      expect p, tkFinally
      expect p, tkColon
      pStmt p
      wrap p, m0, FinL
    elif (p.tok.kind in {tkElse}):
      expect p, tkElse
      expect p, tkColon
      pStmt p
      wrap p, m0, ElseL
    else:
      ruleError p, "extraPostExprBlock", false
  else:
    ruleError p, "extraPostExprBlock", (p.tok.kind in Tk15 and indClass(p) in {icNoInd, icLt, icGt}) or indClass(p) notin {icEq}
  discardUnused m0

proc pPostExprBlocks*(p: var Parser) =
  let m0 = mark(p)
  if (p.tok.kind in {tkColon, tkDo} and indClass(p) in {icNoInd}):
    checkInd p, {icNoInd}
    if (p.tok.kind in {tkDo}):
      pDoBlock(p, true)
      while (p.tok.kind in Tk15 and indClass(p) in {icEq}):
        let m166 = mark(p)
        pExtraPostExprBlock p
        discardUnused m166
    elif (p.tok.kind in {tkColon}):
      expect p, tkColon
      if (p.tok.kind in {tkComment} and indClass(p) in {icNoInd}):
        let m167 = mark(p)
        pTrailComment p
        discardUnused m167
      let m168 = mark(p)
      if (p.tok.kind in Tk15 and indClass(p) in {icEq}):
        pExtraPostExprBlock p
      elif (p.tok.kind in Tk21 and indClass(p) in {icGt}) or (p.tok.kind in Tk9):
        pStmt p
      else:
        ruleError p, "postExprBlocks", (p.tok.kind in Tk22 and indClass(p) in {icNoInd, icLt, icEq}) or (p.tok.kind in {tkDo, tkElif, tkElse} and indClass(p) in {icNoInd, icLt, icGt}) or (p.tok.kind in {tkExcept, tkFinally} and indClass(p) in {icNoInd, icLt})
      discardUnused m168
      while (p.tok.kind in Tk15 and indClass(p) in {icEq}):
        let m169 = mark(p)
        pExtraPostExprBlock p
        discardUnused m169
    else:
      ruleError p, "postExprBlocks", false
  else:
    ruleError p, "postExprBlocks", (p.tok.kind in {tkColon, tkDo} and indClass(p) in {icLt, icEq, icGt}) or indClass(p) notin {icNoInd}
  discardUnused m0

proc pExprBlocks*(p: var Parser) =
  let m0 = mark(p)
  pExpr p
  if (p.tok.kind in {tkColon, tkDo} and indClass(p) in {icNoInd}):
    let m170 = mark(p)
    pPostExprBlocks p
    discardUnused m170
  let m = m0
  attachBlocks p, m
  discardUnused m0

proc pExprStmt*(p: var Parser) =
  let m0 = mark(p)
  if (p.tok.kind in Tk4):
    pSimpleExpr(p, -1, pmTrySimple)
    if (p.tok.kind in {tkEquals}):
      var at171 = m0.info
      at171 = p.info
      expect p, tkEquals
      pOptInd p
      pExprBlocks p
      wrapAt p, m0, AsgnL, at171
    elif (p.tok.kind in Tk2 and indClass(p) in {icNoInd}):
      checkInd p, {icNoInd}
      let m172 = mark(p)
      pExprEqExpr p
      while (p.tok.kind in {tkComma} and indClass(p) in {icNoInd, icEq, icGt}):
        pOptPar p
        pComma p
        pOptInd p
        pExprEqExpr p
      if ((p.tok.kind in {tkComma})) and indClass(p) == icGt:
        indentError p
      discardUnused m172
      if (p.tok.kind in {tkColon, tkDo} and indClass(p) in {icNoInd}):
        let m173 = mark(p)
        pPostExprBlocks p
        discardUnused m173
      let m = m0
      wrapLikeFirst p, m, CmdL      # `newTree(nkCommand, a.info, a)`
    elif (p.tok.kind in {tkColon, tkDo} and indClass(p) in {icNoInd}):
      if (p.tok.kind in {tkColon, tkDo} and indClass(p) in {icNoInd}):
        let m174 = mark(p)
        pPostExprBlocks p
        discardUnused m174
      let m = m0
      attachBlocks p, m
    else:
      if (p.tok.kind in {tkColon, tkDo} and indClass(p) in {icNoInd}):
        let m175 = mark(p)
        pPostExprBlocks p
        discardUnused m175
      let m = m0
      attachBlocks p, m
  else:
    ruleError p, "exprStmt", false
  discardUnused m0

