            pComma p
            pExpr p
            discardUnused m178
          wrap p, m0, ImportL
      else:
        ruleError p, "importStmt", false
    else:
      ruleError p, "importStmt", (p.tok.kind in {tkComment} and indClass(p) in {icLt, icEq, icGt}) or (p.tok.kind in Tk2 and indClass(p) in {icLt, icEq}) or indClass(p) notin {icNoInd, icGt}
  else:
    ruleError p, "importStmt", false
