proc pComplexOrSimpleStmt*(p: var Parser) =
  let m0 = mark(p)
  if (p.tok.kind in Tk30):
    let m320 = mark(p)
    if (p.tok.kind in {tkIf}):
      pIfStmt p
    elif (p.tok.kind in {tkWhen}):
      pWhenStmt p
    elif (p.tok.kind in {tkWhile}):
      pWhileStmt p
    elif (p.tok.kind in {tkTry}):
      pTryStmt p
    elif (p.tok.kind in {tkFor}):
      pForStmt p
    elif (p.tok.kind in {tkBlock}):
      pBlockStmt p
    elif (p.tok.kind in {tkStatic}):
      pStaticStmt p
    elif (p.tok.kind in {tkDefer}):
      pDeferStmt p
    elif (p.tok.kind in {tkAsm}):
      pAsmStmt p
    elif (p.tok.kind in {tkBind}):
      pBindStmt p
    elif (p.tok.kind in {tkMixin}):
      pMixinStmt p
    elif (p.tok.kind in {tkCase}):
      pCaseStmt p
    else:
      ruleError p, "complexOrSimpleStmt", false
    discardUnused m320
  elif (p.tok.kind in {tkExcept}):
    expect p, tkExcept
    emitEmpty p
    pColcom p
    pStmt p
    wrap p, m0, ExceptL
  elif (p.tok.kind in {tkFinally}):
    expect p, tkFinally
    pColcom p
    pStmt p
    wrap p, m0, FinL
  elif (p.tok.kind in {tkProc}):
    pushInfo p
    expect p, tkProc
    pRoutine(p, ProcL)
    popInfo p
  elif (p.tok.kind in {tkMethod}):
    pushInfo p
    expect p, tkMethod
    pRoutine(p, MethodL)
    popInfo p
  elif (p.tok.kind in {tkFunc}):
    pushInfo p
    expect p, tkFunc
    pRoutine(p, FuncL)
    popInfo p
  elif (p.tok.kind in {tkIterator}):
    pushInfo p
    expect p, tkIterator
    pRoutine(p, IteratorL)
    popInfo p
  elif (p.tok.kind in {tkMacro}):
    pushInfo p
    expect p, tkMacro
    pRoutine(p, MacroL)
    popInfo p
  elif (p.tok.kind in {tkTemplate}):
    pushInfo p
    expect p, tkTemplate
    pRoutine(p, TemplateL)
    popInfo p
  elif (p.tok.kind in {tkConverter}):
    pushInfo p
    expect p, tkConverter
    pRoutine(p, ConverterL)
    popInfo p
  elif (p.tok.kind in {tkType}):
    expect p, tkType
    if (p.tok.kind in {tkAccent, tkComment, tkSymbol} and indClass(p) in {icNoInd, icGt}):
      pSection_typeDef p
    elif (p.tok.kind in {tkParLe}):
      var at321 = m0.info
      expect p, tkParLe
      at321 = p.info
      pPrimary(p, pmTypeDesc)
      expect p, tkParRi
      wrapAt p, m0, TypeofL, at321
      var prec322 = getPrecedence(p)
      while prec322 >= -1 and indClass(p) == icNoInd:
        let assoc322 = (if isRightAssoc(p): 0 else: 1)
        let opassoc322 = p.info
        insertLeafAt p, m0, p.tok.s
        getTok p
        afterOperator p
        pSimpleExpr(p, prec322 + assoc322, pmNormal)
        wrapAt p, m0, InfixL, opassoc322
        prec322 = getPrecedence(p)
    else:
      ruleError p, "complexOrSimpleStmt", (p.tok.kind in {tkAccent, tkComment, tkSymbol} and indClass(p) in {icLt, icEq})
  elif (p.tok.kind in {tkConst}):
    pushSection p, ConstL
    expect p, tkConst
    pSection_constant p
    popSection p
  elif (p.tok.kind in {tkLet}):
    pushSection p, LetL
    expect p, tkLet
    pSection_variable p
    popSection p
  elif (p.tok.kind in {tkVar}):
    pushSection p, VarL
    expect p, tkVar
    pSection_variable p
    popSection p
  elif (p.tok.kind in {tkUsing}):
    pushLastSection p
    expect p, tkUsing
    pSection_variable p
    popSection p
    wrap p, m0, UsingL
  else:
    pSimpleStmt p
  discardUnused m0

proc pStmt*(p: var Parser) =
  let m0 = mark(p)
  if (p.tok.kind in Tk8 and indClass(p) in {icGt}):
    pushInd p
    pComplexOrSimpleStmt p
    while (p.tok.kind in Tk8 and indClass(p) in {icEq}) or (p.tok.kind in {tkSemiColon}):
      let m323 = mark(p)
      let m324 = mark(p)
      if (p.tok.kind in Tk8 and indClass(p) in {icEq}):
        checkInd p, {icEq}
        pComplexOrSimpleStmt p
      elif (p.tok.kind in {tkSemiColon}):
        expect p, tkSemiColon
        if (p.tok.kind in Tk8 and indClass(p) in {icNoInd, icEq}):
          let m325 = mark(p)
          pOptSameInd p
          pComplexOrSimpleStmt p
          discardUnused m325
      else:
        ruleError p, "stmt", (p.tok.kind in Tk8 and indClass(p) in {icNoInd, icLt, icGt})
      discardUnused m324
      discardUnused m323
    pStmtListEnd p
    popInd p
    wrap p, m0, StmtsL
  elif (p.tok.kind in Tk31 and indClass(p) in {icNoInd, icLt, icEq}):
    if ((p.tok.kind in Tk9 and indClass(p) in {icNoInd, icLt, icEq})) and inSemiStmtList(p):
      pNotInd p
      pSimpleStmt p
    elif (p.tok.kind in Tk9 and indClass(p) in {icNoInd}):
      checkInd p, {icNoInd}
      let m326 = mark(p)
      pSimpleStmt p
      while (p.tok.kind in {tkSemiColon}):
        expect p, tkSemiColon
        pSimpleStmt p
      discardUnused m326
      wrap p, m0, StmtsL
    else:
      ruleError p, "stmt", (p.tok.kind in Tk9 and indClass(p) in {icGt})
  else:
    ruleError p, "stmt", (p.tok.kind in Tk32 and indClass(p) in {icNoInd, icLt, icEq})
  discardUnused m0

proc pStmtListEnd*(p: var Parser) =
  let m0 = mark(p)
  let m = m0
  stmtListEnd p     # `parseStmt` tries a statement on anything else
  discardUnused m0

proc pOneLinerStart*(p: var Parser) =
  let m0 = mark(p)
  let m327 = mark(p)
  if (p.tok.kind in {tkReturn}):
    expect p, tkReturn
  elif (p.tok.kind in {tkRaise}):
    expect p, tkRaise
  elif (p.tok.kind in {tkYield}):
    expect p, tkYield
